CREATE VIEW gold.rpt_sap_customer_reconciliation AS SELECT s.calmonth, s.customer, s.bill_val sales_bill_val, b.bill_val b2b_bill_val, s.bill_val - b.bill_val bill_val_variance, CASE WHEN b.bill_val > 0 THEN s.bill_val / b.bill_val END sales_to_b2b_ratio, CASE WHEN b.bill_val > 0 THEN s.bill_val / b.bill_val END sell_in_to_sell_out_ratio, CASE WHEN s.bill_val > 0 THEN b.bill_val / s.bill_val END sell_out_to_sell_in_ratio, CASE WHEN b.bill_val > 0 THEN abs(s.bill_val - b.bill_val) / b.bill_val END bill_val_pct_variance FROM gold.corr_sales_customer_month s INNER JOIN gold.corr_b2b_customer_month b ON s.customer = b.customer AND s.calmonth = b.calmonth
